import json
import struct
import zipfile
from pathlib import Path

root = Path('qa-artifacts/current-game-screenshots')
data = json.loads((root / 'manifest.json').read_text(encoding='utf-8'))
catalog = json.loads((root / 'catalog.json').read_text(encoding='utf-8'))
rows = data['results']
assert len(rows) == len(catalog) * len(data['profiles']) and all(r['captured'] for r in rows)
for row in rows:
    raw = (root / row['file']).read_bytes()
    assert raw[:8] == b'\x89PNG\r\n\x1a\n'
    assert struct.unpack('>II', raw[16:24]) == (row['width'], row['height'])
entries = [{**game, 'screens': {p['name']: next(r['file'] for r in rows if r['key'] == game['key'] and r['profile'] == p['name']) for p in data['profiles']}} for game in catalog]
html = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>All game screenshots</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0b1821;color:#f8efd8;font:16px system-ui}header{padding:24px;border-bottom:1px solid #344b54;background:#0d202b}h1{font-size:28px;margin:0 0 8px}p{color:#c1d2d9}nav{display:flex;flex-wrap:wrap;gap:10px;align-items:center}button,select,input,a.download{font:inherit;padding:10px 13px;border:1px solid #708992;border-radius:7px;background:#183442;color:#fff2d1}button{cursor:pointer}button[aria-pressed=true]{background:#e4bd6d;color:#112b39}a{color:#f3d086}a.download{margin-left:auto;text-decoration:none}main{max-width:1550px;margin:auto;padding:24px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}article{min-width:0}article button{padding:0;border:1px solid #49626b;background:#07131a;display:block;width:100%;overflow:hidden}article img{display:block;width:100%;height:auto}h2{font-size:18px;margin:10px 0 5px}.meta{display:flex;flex-wrap:wrap;gap:10px;justify-content:space-between;color:#bbced6;font-size:13px}dialog{width:min(98vw,1500px);max-width:98vw;height:95vh;max-height:95vh;padding:16px;border:1px solid #728991;border-radius:10px;background:#091821;color:#fff1d1}dialog::backdrop{background:#000d}.viewer{height:calc(100% - 65px);display:flex;justify-content:center;align-items:center}.viewer img{max-height:100%;max-width:100%;object-fit:contain}.toolbar{display:flex;gap:10px;align-items:center;min-height:55px}.toolbar strong{flex:1}footer{text-align:center;padding:16px;color:#aebfc8}@media(max-width:850px){main{grid-template-columns:1fr;padding:16px}a.download{margin-left:0}}</style>
<header><h1>The latest look · all 37 games</h1><p>Live gameplay with upgraded Barratt, Bran, Mochi and Vex, original enemies and island environments. Desktop and landscape phone captures.</p><p id="summary"></p><nav><button id="desktop" aria-pressed="true">Desktop</button><button id="phone" aria-pressed="false">Landscape phone</button><select id="island" aria-label="Filter by island"><option value="all">All islands</option></select><input id="search" type="search" aria-label="Find a game" placeholder="Find a game"><a class="download" href="all-game-screenshots.zip" download>Download all screenshots</a></nav></header><main id="gallery"></main><footer>Current playable game captures · click a screenshot to view full size · <a href="graphics-pass.md">Graphics pass and verification notes</a></footer><dialog><div class="toolbar"><button id="previous" aria-label="Previous screenshot">←</button><strong id="caption"></strong><button id="next" aria-label="Next screenshot">→</button><a id="original" download>Save image</a><button id="close">Close</button></div><div class="viewer"><img id="large" alt=""></div></dialog>
<script>const games=__GAMES__;let profile='desktop',shown=games,index=0;const gallery=document.querySelector('#gallery'),dialog=document.querySelector('dialog');
for(const [id,name] of new Map(games.map(g=>[g.island,g.islandName]))){const option=document.createElement('option');option.value=id;option.textContent=name;document.querySelector('#island').append(option)}
function render(){const island=document.querySelector('#island').value,query=document.querySelector('#search').value.toLowerCase();shown=games.filter(g=>(island==='all'||String(g.island)===island)&&g.title.toLowerCase().includes(query));gallery.replaceChildren();document.querySelector('#summary').textContent=games.length+' games · '+games.length*2+' screenshots · '+(profile==='desktop'?'1187 × 884 desktop':'844 × 390 landscape phone')+' · showing '+shown.length;
shown.forEach((g,i)=>{const article=document.createElement('article'),button=document.createElement('button'),image=document.createElement('img'),title=document.createElement('h2'),meta=document.createElement('div'),label=document.createElement('span'),link=document.createElement('a');image.src=g.screens[profile];image.alt=g.title+' gameplay screenshot';image.loading='lazy';button.setAttribute('aria-label','View '+g.title+' screenshot');button.append(image);button.onclick=()=>{index=i;view();dialog.showModal()};title.textContent=g.title;meta.className='meta';label.textContent=g.islandName;link.textContent='Play game ↗';link.href=g.route;link.target='_blank';link.rel='noopener';meta.append(label,link);article.append(button,title,meta);gallery.append(article)})}
function view(){const g=shown[index];document.querySelector('#large').src=g.screens[profile];document.querySelector('#large').alt=g.title;document.querySelector('#caption').textContent=g.title+' · '+(profile==='desktop'?'Desktop':'Landscape phone');const a=document.querySelector('#original');a.href=g.screens[profile];a.download=profile+'-'+g.key+'.png'}
for(const name of ['desktop','phone'])document.querySelector('#'+name).onclick=()=>{profile=name;for(const key of ['desktop','phone'])document.querySelector('#'+key).setAttribute('aria-pressed',String(key===name));render()};document.querySelector('#island').onchange=render;document.querySelector('#search').oninput=render;document.querySelector('#close').onclick=()=>dialog.close();document.querySelector('#previous').onclick=()=>{index=(index+shown.length-1)%shown.length;view()};document.querySelector('#next').onclick=()=>{index=(index+1)%shown.length;view()};document.addEventListener('keydown',event=>{if(!dialog.open)return;if(event.key==='ArrowRight')document.querySelector('#next').click();if(event.key==='ArrowLeft')document.querySelector('#previous').click()});if(location.protocol==='file:')document.querySelector('.download').hidden=true;render();</script></html>'''
(root / 'index.html').write_text(html.replace('__GAMES__', json.dumps(entries).replace('<', '\\u003c')), encoding='utf-8')
(root / 'README.txt').write_text(f'SATs Legends: {len(catalog)} games, {len(rows)} current gameplay screenshots.\nOpen index.html to browse desktop and landscape phone screenshots.\nThe highest available level of each game is captured. Captured from the current working tree with upgraded original heroes.\n', encoding='utf-8')
summary = {'games': len(catalog), 'screenshots': len(rows), 'profiles': data['profiles'], 'changedFiles': ['scripts/capture-current-game-screenshots.mjs', 'scripts/create-current-game-gallery.py', 'qa-artifacts/current-game-screenshots/*'], 'assumptions': ['One representative screenshot per game per viewport; highest available level selected from the current live catalogue.', 'Use desktop and landscape phone layouts.', 'Use an isolated repository QA account fixture.'], 'runtimeErrors': [{'game': r['title'], 'profile': r['profile'], 'errors': r['runtimeErrors']} for r in rows if r['runtimeErrors']], 'externalLegacyAssumptionsUsed': False}
(root / 'change-summary.json').write_text(json.dumps(summary, indent=2) + '\n', encoding='utf-8')
with zipfile.ZipFile(root / 'all-game-screenshots.zip', 'w', compression=zipfile.ZIP_STORED) as archive:
    report = Path('qa-artifacts/latest-visual-audit/change-summary.md')
    if report.exists():
        (root / 'graphics-pass.md').write_text(report.read_text(encoding='utf-8'), encoding='utf-8')
        archive.write(root / 'graphics-pass.md', 'graphics-pass.md')
    for name in ['index.html', 'manifest.json', 'catalog.json', 'README.txt', 'change-summary.json']:
        archive.write(root / name, name)
    for row in rows:
        archive.write(root / row['file'], row['file'])
with zipfile.ZipFile(root / 'all-game-screenshots.zip') as archive:
    assert archive.testzip() is None
print(json.dumps({'games': len(catalog), 'screenshots': len(rows), 'zipBytes': (root / 'all-game-screenshots.zip').stat().st_size, 'runtimeErrors': len(summary['runtimeErrors'])}))
